$reportDir = Join-Path $root 'reports/agent-task'
$summaryPath = Join-Path $reportDir 'summary.json'
$model = 'gpt-5.6-luna'
$allowedTestScopes = @('BslOnly','EpfBuildOnly')
$maxRepairAttempts = 2
$codexExecutablePath = ''
$codexExecutableKind = ''
$agentRuns = @()
$testHistory = @()
